diff --git a/shell/globalshortcutsmodel.cpp b/shell/globalshortcutsmodel.cpp
new file mode 100644
index 0000000000..d7ecfbcec5
--- /dev/null
+++ b/shell/globalshortcutsmodel.cpp
@@ -0,0 +1,131 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "globalshortcutsmodel.h"
+
+#include <QCollator>
+#include <QDBusMetaType>
+#include <QDBusPendingCallWatcher>
+#include <QDBusPendingReply>
+#include <QKeySequence>
+
+#include <KGlobalShortcutInfo>
+
+#include "kglobalaccel_component_interface.h"
+#include "kglobalaccel_interface.h"
+
+using namespace Qt::StringLiterals;
+
+GlobalShortcutsModel::GlobalShortcutsModel(QObject *parent)
+    : QAbstractListModel(parent)
+    , m_interface(new KGlobalAccelInterface(u"org.kde.kglobalaccel"_s, u"/kglobalaccel"_s, QDBusConnection::sessionBus(), this))
+{
+    qDBusRegisterMetaType<QKeySequence>();
+    qDBusRegisterMetaType<QList<QKeySequence>>();
+    qDBusRegisterMetaType<KGlobalShortcutInfo>();
+    qDBusRegisterMetaType<QList<KGlobalShortcutInfo>>();
+}
+
+GlobalShortcutsModel::~GlobalShortcutsModel() = default;
+
+int GlobalShortcutsModel::rowCount(const QModelIndex &parent) const
+{
+    return parent.isValid() ? 0 : m_shortcuts.size();
+}
+
+QVariant GlobalShortcutsModel::data(const QModelIndex &index, int role) const
+{
+    if (!checkIndex(index, CheckIndexOption::IndexIsValid)) {
+        return {};
+    }
+    const Shortcut &shortcut = m_shortcuts.at(index.row());
+    switch (role) {
+    case Qt::DisplayRole:
+        return shortcut.name;
+    case ComponentRole:
+        return shortcut.component;
+    case KeysRole:
+        return shortcut.keys;
+    }
+    return {};
+}
+
+QHash<int, QByteArray> GlobalShortcutsModel::roleNames() const
+{
+    return {
+        {Qt::DisplayRole, "display"},
+        {ComponentRole, "component"},
+        {KeysRole, "keys"},
+    };
+}
+
+void GlobalShortcutsModel::reload()
+{
+    const int generation = ++m_generation;
+    auto componentsWatcher = new QDBusPendingCallWatcher(m_interface->allComponents(), this);
+    connect(componentsWatcher, &QDBusPendingCallWatcher::finished, this, [this, generation](QDBusPendingCallWatcher *componentsWatcher) {
+        componentsWatcher->deleteLater();
+        const QDBusPendingReply<QList<QDBusObjectPath>> componentsReply = *componentsWatcher;
+        if (generation != m_generation || componentsReply.isError()) {
+            return;
+        }
+
+        const QList<QDBusObjectPath> paths = componentsReply.value();
+        if (paths.isEmpty()) {
+            beginResetModel();
+            m_shortcuts.clear();
+            endResetModel();
+            return;
+        }
+        auto pending = std::make_shared<QList<Shortcut>>();
+        auto remaining = std::make_shared<qsizetype>(paths.size());
+        for (const QDBusObjectPath &path : paths) {
+            KGlobalAccelComponentInterface component(m_interface->service(), path.path(), m_interface->connection());
+            auto watcher = new QDBusPendingCallWatcher(component.allShortcutInfos(), this);
+            connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, generation, pending, remaining](QDBusPendingCallWatcher *watcher) {
+                watcher->deleteLater();
+                const QDBusPendingReply<QList<KGlobalShortcutInfo>> reply = *watcher;
+                if (generation != m_generation) {
+                    return;
+                }
+                if (!reply.isError()) {
+                    for (const KGlobalShortcutInfo &info : reply.value()) {
+                        QStringList keys;
+                        for (const QKeySequence &key : info.keys()) {
+                            if (!key.isEmpty()) {
+                                keys.append(key.toString(QKeySequence::NativeText));
+                            }
+                        }
+                        if (keys.isEmpty()) {
+                            continue;
+                        }
+                        const QString component = info.componentFriendlyName().isEmpty() ? info.componentUniqueName() : info.componentFriendlyName();
+                        const QString name = info.friendlyName().isEmpty() ? info.uniqueName() : info.friendlyName();
+                        pending->append({component, name, keys});
+                    }
+                }
+                if (--*remaining > 0) {
+                    return;
+                }
+
+                QCollator collator;
+                collator.setCaseSensitivity(Qt::CaseInsensitive);
+                collator.setNumericMode(true);
+                std::ranges::sort(*pending, [&collator](const Shortcut &a, const Shortcut &b) {
+                    if (const int order = collator.compare(a.component, b.component); order != 0) {
+                        return order < 0;
+                    }
+                    return collator.compare(a.name, b.name) < 0;
+                });
+                beginResetModel();
+                m_shortcuts = std::move(*pending);
+                endResetModel();
+            });
+        }
+    });
+}
+
+#include "moc_globalshortcutsmodel.cpp"
