+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <QAbstractListModel>
+#include <qqmlregistration.h>
+
+class KGlobalAccelInterface;
+
+class GlobalShortcutsModel : public QAbstractListModel
+{
+    Q_OBJECT
+    QML_ELEMENT
+public:
+    enum Roles {
+        ComponentRole = Qt::UserRole + 1,
+        KeysRole,
+    };
+    Q_ENUM(Roles)
+
+    explicit GlobalShortcutsModel(QObject *parent = nullptr);
+    ~GlobalShortcutsModel() override;
+
+    int rowCount(const QModelIndex &parent = QModelIndex()) const override;
+    QVariant data(const QModelIndex &index, int role = Qt::DisplayRole) const override;
+    QHash<int, QByteArray> roleNames() const override;
+
+    Q_INVOKABLE void reload();
+
+private:
+    struct Shortcut {
+        QString component;
+        QString name;
+        QStringList keys;
+    };
+
+    KGlobalAccelInterface *const m_interface;
+    QList<Shortcut> m_shortcuts;
+    int m_generation = 0;
+};
