+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+import QtQuick
+import QtQuick.Layouts
+
+import org.kde.config as KConfig
+import org.kde.kcmutils as KCMUtils
+import org.kde.kirigami as Kirigami
+import org.kde.kitemmodels as KItemModels
+import org.kde.ksvg as KSvg
+import org.kde.plasma.components as PlasmaComponents3
+import org.kde.plasma.extras as PlasmaExtras
+
+import org.kde.plasma.workspace.shortcuts
+
+ShortcutsWindow {
+    id: root
+
+    title: i18n("Keyboard Shortcuts")
+
+    LayoutMirroring.enabled: Application.layoutDirection === Qt.RightToLeft
+    LayoutMirroring.childrenInherit: true
+
+    onVisibleChanged: {
+        if (visible) {
+            searchField.text = "";
+            shortcutsModel.reload();
+            searchField.forceActiveFocus();
+        }
+    }
+
+    GlobalShortcutsModel {
+        id: shortcutsModel
+    }
+
+    Shortcut {
+        sequences: [StandardKey.Cancel]
+        onActivated: root.visible = false
+    }
+
+    Rectangle {
+        anchors.fill: parent
+        color: Qt.rgba(0, 0, 0, 0.5)
+
+        MouseArea {
+            anchors.fill: parent
+            onClicked: root.visible = false
+        }
+    }
+
+    KSvg.FrameSvgItem {
+        id: card
+
+        anchors.centerIn: parent
+        width: Math.min(parent.width - Kirigami.Units.gridUnit * 4, Kirigami.Units.gridUnit * 40)
+        height: Math.min(parent.height - Kirigami.Units.gridUnit * 4, Kirigami.Units.gridUnit * 40)
+        imagePath: "solid/dialogs/background"
+
+        // Don't close when clicking inside the card
+        MouseArea {
+            anchors.fill: parent
+        }
+
+        ColumnLayout {
+            anchors {
+                fill: parent
+                leftMargin: card.margins.left + Kirigami.Units.smallSpacing
+                topMargin: card.margins.top + Kirigami.Units.smallSpacing
+                rightMargin: card.margins.right + Kirigami.Units.smallSpacing
+                bottomMargin: card.margins.bottom + Kirigami.Units.smallSpacing
+            }
+            spacing: Kirigami.Units.smallSpacing
+
+            RowLayout {
+                Layout.fillWidth: true
+                spacing: Kirigami.Units.smallSpacing
+
+                PlasmaExtras.Heading {
+                    Layout.fillWidth: true
+                    level: 1
+                    text: root.title
+                    elide: Text.ElideRight
+                }
+
+                PlasmaComponents3.ToolButton {
+                    visible: KConfig.KAuthorized.authorizeControlModule("kcm_keys")
+                    icon.name: "configure"
+                    text: i18nc("@action:button", "Configure…")
+                    onClicked: {
+                        root.visible = false;
+                        KCMUtils.KCMLauncher.openSystemSettings("kcm_keys");
+                    }
+                }
+            }
+
+            PlasmaExtras.SearchField {
+                id: searchField
+                Layout.fillWidth: true
+                Keys.onDownPressed: shortcutsList.scroll(Kirigami.Units.gridUnit * 2)
+                Keys.onUpPressed: shortcutsList.scroll(-Kirigami.Units.gridUnit * 2)
+                Keys.onPressed: event => {
+                    if (event.key === Qt.Key_PageDown) {
+                        shortcutsList.scroll(shortcutsList.height);
+                    } else if (event.key === Qt.Key_PageUp) {
+                        shortcutsList.scroll(-shortcutsList.height);
+                    }
+                }
+            }
+
+            PlasmaComponents3.ScrollView {
+                Layout.fillWidth: true
+                Layout.fillHeight: true
+
+                ListView {
+                    id: shortcutsList
+
+                    function scroll(delta: real): void {
+                        contentY = Math.max(originY, Math.min(contentY + delta, originY + contentHeight - height));
+                    }
+
+                    clip: true
+                    reuseItems: true
+                    model: KItemModels.KSortFilterProxyModel {
+                        sourceModel: shortcutsModel
+                        filterString: searchField.text
+                        filterRowCallback: (sourceRow, sourceParent) => {
+                            if (filterString.length === 0) {
+                                return true;
+                            }
+                            const index = sourceModel.index(sourceRow, 0, sourceParent);
+                            const needle = filterString.toLocaleLowerCase();
+                            return [sourceModel.data(index, Qt.DisplayRole),
+                                    sourceModel.data(index, GlobalShortcutsModel.ComponentRole),
+                                    sourceModel.data(index, GlobalShortcutsModel.KeysRole).join(" ")]
+                                .some(text => text.toLocaleLowerCase().includes(needle));
+                        }
+                    }
+
+                    section.property: "component"
+                    section.delegate: PlasmaExtras.ListSectionHeader {
+                        required property string section
+                        width: ListView.view.width
+                        text: section
+                    }
+
+                    delegate: RowLayout {
+                        required property string display
+                        required property var keys
+
+                        width: ListView.view.width
+                        spacing: Kirigami.Units.largeSpacing
+
+                        PlasmaComponents3.Label {
+                            Layout.fillWidth: true
+                            Layout.leftMargin: Kirigami.Units.largeSpacing
+                            topPadding: Kirigami.Units.smallSpacing
+                            bottomPadding: Kirigami.Units.smallSpacing
+                            text: parent.display
+                            wrapMode: Text.Wrap
+                        }
+
+                        Repeater {
+                            model: parent.keys
+
+                            Rectangle {
+                                required property string modelData
+
+                                Layout.rightMargin: Kirigami.Units.smallSpacing
+                                implicitWidth: keyLabel.implicitWidth + Kirigami.Units.largeSpacing
+                                implicitHeight: keyLabel.implicitHeight + Kirigami.Units.smallSpacing
+                                radius: Kirigami.Units.cornerRadius
+                                color: "transparent"
+                                border.color: Qt.alpha(Kirigami.Theme.textColor, 0.3)
+
+                                PlasmaComponents3.Label {
+                                    id: keyLabel
+                                    anchors.centerIn: parent
+                                    text: parent.modelData
+                                    textFormat: Text.PlainText
+                                }
+                            }
+                        }
+                    }
+
+                    PlasmaExtras.PlaceholderMessage {
+                        anchors.centerIn: parent
+                        width: parent.width - Kirigami.Units.gridUnit * 4
+                        visible: shortcutsList.count === 0 && searchField.text.length > 0
+                        iconName: "edit-none"
+                        text: i18nc("@info:placeholder", "No matching shortcuts")
+                    }
+                }
+            }
+        }
+    }
+}
