+void ShellCorona::toggleShortcutsOverview()
+{
+    if (!m_shortcutsOverview) {
+        QQmlComponent component(PlasmaQuick::globalEngine().get(), "org.kde.plasma.workspace.shortcuts", "ShortcutsOverview");
+        if (component.status() != QQmlComponent::Ready) {
+            qCWarning(PLASMASHELL) << "Failed to load the keyboard shortcuts overview" << component.errorString();
+            return;
+        }
+        auto qmlContext = new QQmlContext(PlasmaQuick::globalEngine().get(), this);
+        auto i18nContext = new KLocalizedQmlContext(qmlContext);
+        qmlContext->setContextObject(i18nContext);
+        QQmlEngine::setContextForObject(i18nContext, qmlContext);
+        m_shortcutsOverview.reset(component.create(qmlContext));
+        if (!m_shortcutsOverview) {
+            qCWarning(PLASMASHELL) << "Failed to create the keyboard shortcuts overview" << component.errorString();
+            return;
+        }
+    }
+    m_shortcutsOverview->setProperty("visible", !m_shortcutsOverview->property("visible").toBool());
+}
