+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "shortcutswindow.h"
+
+#include <QCursor>
+#include <QGuiApplication>
+#include <QScreen>
+
+#include <KWindowSystem>
+#include <LayerShellQt/Window>
+
+using namespace Qt::StringLiterals;
+
+ShortcutsWindow::ShortcutsWindow(QWindow *parent)
+    : QQuickWindow(parent)
+{
+    setColor(Qt::transparent);
+
+    if (KWindowSystem::isPlatformWayland()) {
+        auto layerWindow = LayerShellQt::Window::get(this);
+        layerWindow->setLayer(LayerShellQt::Window::LayerOverlay);
+        layerWindow->setAnchors(LayerShellQt::Window::Anchors(LayerShellQt::Window::AnchorTop | LayerShellQt::Window::AnchorBottom
+                                                              | LayerShellQt::Window::AnchorLeft | LayerShellQt::Window::AnchorRight));
+        layerWindow->setExclusiveZone(-1);
+        layerWindow->setKeyboardInteractivity(LayerShellQt::Window::KeyboardInteractivityExclusive);
+        layerWindow->setScope(u"shortcuts"_s);
+        layerWindow->setWantsToBeOnActiveScreen(true);
+    } else {
+        setFlags(Qt::FramelessWindowHint | Qt::WindowStaysOnTopHint | Qt::Tool);
+    }
+}
+
+void ShortcutsWindow::showEvent(QShowEvent *event)
+{
+    if (!KWindowSystem::isPlatformWayland()) {
+        if (QScreen *screen = QGuiApplication::screenAt(QCursor::pos())) {
+            setScreen(screen);
+            setGeometry(screen->geometry());
+        }
+        KWindowSystem::activateWindow(this);
+    }
+    QQuickWindow::showEvent(event);
+}
+
+#include "moc_shortcutswindow.cpp"
